(function() {
	const gradeConstants = {
		activities: {
			manual: "manual"
		},
		maxLengths : {
			assignTitle: 400
		},
		attendanceReasons: {
			released: "ОСВ",
			missed: "ОТ"
		},
		assignmentTypes: {
			themeWork: 2,
			homeWork: 3,
			controlWork: 4,
			dictation: 8,
			lessonAnswer: 10,
			testing: 14,
			tkrAssignType: 15,
			DKR: 16
		},
		testPlansTypes: [2, 4, 8, 14, 16],
		highLightTypes: [2, 4, 8, 14, 15, 16]
	};

	if (typeof(sys) != 'undefined' && sys.constants != null) {
		sys.constants.grade = gradeConstants;
	}

	//для поддержки js модульности
	(function (exp, name) {
		var exported = false;
		if (typeof module !== 'undefined' && module.exports) {
			module.exports = exp;
			exported = true;
		}
		if (typeof exports !== 'undefined') {
			exports = exp;
			exported = true;
		}
		if (!exported && (typeof window !== 'undefined' && typeof (name) !== "undefined")) {
			window[name] = exp;
		}
		if (typeof root !== 'undefined' && typeof (name) !== "undefined") {
			root[name] = exp;
		}
	})(gradeConstants);
})();



